@DriftDatabase(
  tables: [
    Photos,
    Albums,
    Tags,
    PhotoTags,
    Vault,
    Thumbnails,
    SyncState,
    BackupState,
    EncryptionVersions,
    ImportJobs,
    ShareExports,
    TrashItems,
    AppSettings,
    SecurityEvents,
    ChatMessages,
    OutboxMessages,
  ],
)
class VaultDatabase extends _$VaultDatabase {
  VaultDatabase() : super(_openConnection());

  /// For tests, e.g. with `NativeDatabase.memory()`.
  VaultDatabase.forTesting(super.executor);

  @override
  int get schemaVersion => 4;

  @override
  MigrationStrategy get migration => MigrationStrategy(
    onCreate: (m) async {
      await m.createAll();
      await _createChatSearchSchema();
    },
    onUpgrade: (m, from, to) async {
      // v2 introduced the offline chat message cache. It holds only
      // ciphertext, so a failed migration can safely recreate it empty.
      if (from < 2) {
        await m.createTable(chatMessages);
      }
      // v3 introduced the offline send outbox.
      if (from < 3) {
        await m.createTable(outboxMessages);
      }
      // v4 introduced the keyed chat search index. Existing cached messages
      // are indexed lazily the next time their thread is opened.
      if (from < 4) {
        await _createChatSearchSchema();
      }
    },
  );

  /// Tables for the local chat search index.
  ///
  /// Declared in SQL rather than as Drift tables because they are accessed
  /// only through the hand-written queries below.
  ///
  /// `chat_search_tokens` holds keyed hashes of word prefixes (see
  /// `ChatSearchTokenizer`), never words, so — like `chat_messages` — it
  /// reveals no message content without the in-memory thread key.
  Future<void> _createChatSearchSchema() async {
    await customStatement(
      'CREATE INDEX IF NOT EXISTS idx_chat_messages_thread_sent '
      'ON chat_messages (thread_id, sent_at_ms)',
    );
    await customStatement(
      'CREATE TABLE IF NOT EXISTS chat_search_tokens ('
      'token TEXT NOT NULL, '
      'message_id TEXT NOT NULL, '
      'thread_id TEXT NOT NULL, '
      'sent_at_ms INTEGER NOT NULL, '
      'PRIMARY KEY (token, message_id)'
      ') WITHOUT ROWID',
    );
    await customStatement(
      'CREATE INDEX IF NOT EXISTS idx_chat_search_tokens_thread '
      'ON chat_search_tokens (thread_id, token, sent_at_ms DESC)',
    );
    await customStatement(
      'CREATE INDEX IF NOT EXISTS idx_chat_search_tokens_message '
      'ON chat_search_tokens (message_id)',
    );
    await customStatement(
      'CREATE TABLE IF NOT EXISTS chat_search_state ('
      'message_id TEXT NOT NULL PRIMARY KEY, '
      'thread_id TEXT NOT NULL, '
      'sent_at_ms INTEGER NOT NULL, '
      'version INTEGER NOT NULL'
      ') WITHOUT ROWID',
    );
    await customStatement(
      'CREATE INDEX IF NOT EXISTS idx_chat_search_state_thread '
      'ON chat_search_state (thread_id, sent_at_ms)',
    );
  }

  // =========================================================================
  // PHOTO QUERIES
  // =========================================================================

  /// Get non-trashed photos with pagination, ordered by most recent imported first.
  Future<List<VaultPhoto>> getGalleryPhotos({int? limit, int? offset}) async {
    final query = select(photos)
      ..where((p) => p.isTrashed.equals(0))
      ..orderBy([
        (p) => OrderingTerm(
          expression: p.importedTimeMs,
          mode: OrderingMode.desc,
        ),
      ]);
    if (limit != null) {
      query.limit(limit, offset: offset);
    }
    return query.get();
  }

  /// Get trashed photos with pagination.
  Future<List<VaultPhoto>> getTrashedPhotos({int? limit, int? offset}) async {
    final query = select(photos)
      ..where((p) => p.isTrashed.equals(1))
      ..orderBy([
        (p) => OrderingTerm(
          expression: p.trashExpiresAtMs,
          mode: OrderingMode.desc,
        ),
      ]);
    if (limit != null) {
      query.limit(limit, offset: offset);
    }
    return query.get();
  }

  /// Get all photos (including trashed) by album.
  Future<List<VaultPhoto>> getPhotosByAlbum(String albumId) async {
    return (select(photos)
          ..where((p) => p.albumId.equals(albumId) & p.isTrashed.equals(0))
          ..orderBy([
            (p) => OrderingTerm(
              expression: p.importedTimeMs,
              mode: OrderingMode.desc,
            ),
          ]))
        .get();
  }

  /// Check if checksum already exists (duplicate detection).
  Future<bool> photoWithChecksumExists(String checksum) async {
    final count =
        await (select(photos)..where(
              (p) => p.checksumSha256.equals(checksum) & p.isTrashed.equals(0),
            ))
            .get()
            .then((rows) => rows.length);
    return count > 0;
  }

  /// Get single photo by ID (for viewer/editor screens).
  Future<VaultPhoto?> getPhotoById(String id) async {
    return (select(photos)..where((p) => p.id.equals(id))).getSingleOrNull();
  }

  /// Insert new photo with metadata and encrypted file path.
  Future<void> insertPhoto(VaultPhoto photo) async {
    await into(photos).insert(photo);
  }

  /// Update photo (e.g., mark as favorite, move to album, update sync status).
  Future<void> updatePhoto(VaultPhoto photo) async {
    await update(photos).replace(photo);
  }

  /// Move photo to trash (soft delete).
  Future<void> movePhotoToTrash(String photoId, int expiresAtMs) async {
    final photo = await getPhotoById(photoId);
    if (photo != null) {
      await update(photos).replace(
        photo.copyWith(isTrashed: 1, trashExpiresAtMs: Value(expiresAtMs)),
      );
    }
  }

  /// Restore photo from trash.
  Future<void> restorePhotoFromTrash(String photoId) async {
    final photo = await getPhotoById(photoId);
    if (photo != null) {
      await update(photos).replace(
        photo.copyWith(isTrashed: 0, trashExpiresAtMs: const Value(null)),
      );
    }
  }

  /// Permanently delete photo (removes encrypted file marker for cleanup).
  Future<void> permanentlyDeletePhoto(String photoId) async {
    await (delete(photos)..where((p) => p.id.equals(photoId))).go();
    await (delete(photoTags)..where((pt) => pt.photoId.equals(photoId))).go();
  }

  /// Get all trashed photos with expiry < now (for cleanup job).
  Future<List<VaultPhoto>> getExpiredTrashPhotos(int nowMs) async {
    return (select(photos)..where(
          (p) =>
              p.isTrashed.equals(1) &
              (p.trashExpiresAtMs.isSmallerThanValue(nowMs) |
                  p.trashExpiresAtMs.isNull()),
        ))
        .get();
  }

  /// Count photos for gallery stats.
  Future<int> countPhotos({bool includeTrashed = false}) async {
    final query = select(photos);
    if (!includeTrashed) {
      query.where((p) => p.isTrashed.equals(0));
    }
    return query.get().then((rows) => rows.length);
  }

  // =========================================================================
  // TAG QUERIES
  // =========================================================================

  /// Get all tags.
  Future<List<VaultTag>> getAllTags() async {
    return select(tags).get();
  }

  /// Get tags for a specific photo.
  Future<List<VaultTag>> getTagsForPhoto(String photoId) async {
    final query = select(
      tags,
    ).join([innerJoin(photoTags, photoTags.tagId.equalsExp(tags.id))]);
    query.where(photoTags.photoId.equals(photoId));
    return query.map((row) => row.readTable(tags)).get();
  }

  /// Add tag to photo (many-to-many).
  Future<void> addTagToPhoto(String photoId, String tagId) async {
    await into(
      photoTags,
    ).insertOnConflictUpdate(PhotoTagLink(photoId: photoId, tagId: tagId));
  }

  /// Remove tag from photo.
  Future<void> removeTagFromPhoto(String photoId, String tagId) async {
    await (delete(
      photoTags,
    )..where((pt) => pt.photoId.equals(photoId) & pt.tagId.equals(tagId))).go();
  }

  // =========================================================================
  // ALBUM QUERIES
  // =========================================================================

  /// Get all albums.
  Future<List<VaultAlbum>> getAllAlbums() async {
    return select(albums).get();
  }

  /// Insert new album.
  Future<void> insertAlbum(VaultAlbum album) async {
    await into(albums).insert(album);
  }

  /// Update album.
  Future<void> updateAlbum(VaultAlbum album) async {
    await update(albums).replace(album);
  }

  // =========================================================================
  // TRASH QUERIES
  // =========================================================================

  /// Get trash items.
  Future<List<TrashItem>> getTrashItems() async {
    return (select(trashItems)..orderBy([
          (t) => OrderingTerm(expression: t.movedAtMs, mode: OrderingMode.desc),
        ]))
        .get();
  }

  /// Add to trash.
  Future<void> addToTrash(String photoId, int expiresAtMs) async {
    await into(trashItems).insertOnConflictUpdate(
      TrashItem(
        photoId: photoId,
        movedAtMs: DateTime.now().millisecondsSinceEpoch,
        expiresAtMs: expiresAtMs,
        syncDeletePending: 0,
      ),
    );
  }

  /// Remove from trash.
  Future<void> removeFromTrash(String photoId) async {
    await (delete(trashItems)..where((t) => t.photoId.equals(photoId))).go();
  }

  // =========================================================================
  // SYNC STATE QUERIES
  // =========================================================================

  /// Get all objects pending sync.
  Future<List<SyncStateEntry>> getPendingSyncItems() async {
    return (select(
      syncState,
    )..where((s) => s.state.isIn(['local_new', 'pending', 'error']))).get();
  }

  /// Update sync state.
  Future<void> updateSyncState(SyncStateEntry entry) async {
    await update(syncState).replace(entry);
  }

  // =========================================================================
  // BACKUP STATE QUERIES
  // =========================================================================

  /// Get backup state value.
  Future<String?> getBackupStateValue(String key) async {
    final entry = await (select(
      backupState,
    )..where((bs) => bs.key.equals(key))).getSingleOrNull();
    return entry?.value;
  }

  /// Set backup state value.
  Future<void> setBackupStateValue(String key, String value) async {
    await into(backupState).insertOnConflictUpdate(
      BackupStateEntry(
        key: key,
        value: value,
        updatedAtMs: DateTime.now().millisecondsSinceEpoch,
      ),
    );
