  // =========================================================================
  // VAULT METADATA QUERIES
  // =========================================================================

  /// Get vault metadata.
  Future<VaultMetadata?> getVaultMetadata(String vaultId) async {
    return (select(
      vault,
    )..where((v) => v.id.equals(vaultId))).getSingleOrNull();
  }

  /// Insert vault metadata.
  Future<void> insertVaultMetadata(VaultMetadata metadata) async {
    await into(vault).insert(metadata);
  }

  // =========================================================================
  // CLEANUP & MAINTENANCE
  // =========================================================================

  /// Clean up expired trash items and their associated database records.
  Future<int> cleanupExpiredTrash(int nowMs) async {
    final expiredPhotos = await getExpiredTrashPhotos(nowMs);
    for (final photo in expiredPhotos) {
      await permanentlyDeletePhoto(photo.id);
      await removeFromTrash(photo.id);
    }
    return expiredPhotos.length;
  }

  /// Log security event.
  Future<void> logSecurityEvent({
    required String id,
    required String eventType,
    required String severity,
    Map<String, dynamic>? details,
  }) async {
    await into(securityEvents).insert(
      SecurityEvent(
        id: id,
        eventType: eventType,
        severity: severity,
        occurredAtMs: DateTime.now().millisecondsSinceEpoch,
        detailsJson: details != null ? _jsonEncode(details) : null,
      ),
    );
  }

  // =========================================================================
  // CHAT MESSAGE CACHE
  // =========================================================================

  /// Newest-first page of cached messages for a thread.
  Future<List<CachedChatMessage>> getCachedMessages(
    String threadId, {
    int limit = 50,
    int? beforeSentAtMs,
  }) async {
    final query = select(chatMessages)
      ..where(
        (m) => beforeSentAtMs == null
            ? m.threadId.equals(threadId)
            : m.threadId.equals(threadId) &
                  m.sentAtMs.isSmallerThanValue(beforeSentAtMs),
      )
      ..orderBy([
        (m) => OrderingTerm(expression: m.sentAtMs, mode: OrderingMode.desc),
      ])
      ..limit(limit);
    return query.get();
  }

  /// Insert or refresh cached messages.
  Future<void> upsertCachedMessages(List<CachedChatMessage> rows) async {
    if (rows.isEmpty) return;
    await batch((b) => b.insertAllOnConflictUpdate(chatMessages, rows));
  }

  /// Drop a single cached message, used when it is deleted for everyone.
  Future<void> deleteCachedMessage(String messageId) async {
    await transaction(() async {
      await (delete(
        chatMessages,
      )..where((m) => m.messageId.equals(messageId))).go();
      await removeFromSearchIndex([messageId]);
    });
  }

  /// Drop an entire thread's cache.
  Future<void> deleteCachedThread(String threadId) async {
    await transaction(() async {
      await (delete(
        chatMessages,
      )..where((m) => m.threadId.equals(threadId))).go();
      await clearSearchIndexForThread(threadId);
    });
  }

  /// A single cached message, if present.
  Future<CachedChatMessage?> getCachedMessage(String messageId) {
    return (select(
      chatMessages,
    )..where((m) => m.messageId.equals(messageId))).getSingleOrNull();
  }

  /// Oldest-first page of cached messages sent at or after [fromSentAtMs].
  Future<List<CachedChatMessage>> getCachedMessagesFrom(
    String threadId, {
    required int fromSentAtMs,
    int limit = 50,
  }) {
    return (select(chatMessages)
          ..where(
            (m) =>
                m.threadId.equals(threadId) &
                m.sentAtMs.isBiggerOrEqualValue(fromSentAtMs),
          )
          ..orderBy([
            (m) => OrderingTerm(expression: m.sentAtMs),
            (m) => OrderingTerm(expression: m.messageId),
          ])
          ..limit(limit))
        .get();
  }

  /// Number of cached messages in a thread, optionally only those strictly
  /// older than [beforeSentAtMs].
  Future<int> countCachedMessages(String threadId, {int? beforeSentAtMs}) async {
    final count = chatMessages.messageId.count();
    final query = selectOnly(chatMessages)
      ..addColumns([count])
      ..where(
        beforeSentAtMs == null
            ? chatMessages.threadId.equals(threadId)
            : chatMessages.threadId.equals(threadId) &
                  chatMessages.sentAtMs.isSmallerThanValue(beforeSentAtMs),
      );
    return (await query.getSingle()).read(count) ?? 0;
  }

  /// The cached message [offset] positions from the oldest (0 = oldest).
  Future<CachedChatMessage?> getCachedMessageAtOffset(
    String threadId,
    int offset,
  ) {
    return (select(chatMessages)
          ..where((m) => m.threadId.equals(threadId))
          ..orderBy([
            (m) => OrderingTerm(expression: m.sentAtMs),
            (m) => OrderingTerm(expression: m.messageId),
          ])
          ..limit(1, offset: offset < 0 ? 0 : offset))
        .getSingleOrNull();
  }

  /// Oldest and newest cached send times in a thread, or null if empty.
  Future<(int, int)?> getCachedTimeBounds(String threadId) async {
    final min = chatMessages.sentAtMs.min();
    final max = chatMessages.sentAtMs.max();
    final row =
        await (selectOnly(chatMessages)
              ..addColumns([min, max])
              ..where(chatMessages.threadId.equals(threadId)))
            .getSingle();
    final lo = row.read(min);
    final hi = row.read(max);
    if (lo == null || hi == null) return null;
    return (lo, hi);
  }

  // =========================================================================
  // CHAT SEARCH INDEX
  // =========================================================================

  /// Replace the index entries of each message with its [tokens].
  Future<void> indexChatMessages(
    String threadId,
    List<({String messageId, int sentAtMs, List<String> tokens})> entries, {
    required int version,
  }) async {
    if (entries.isEmpty) return;
    await transaction(() async {
      await removeFromSearchIndex([for (final e in entries) e.messageId]);
      await batch((b) {
        for (final e in entries) {
          for (final token in e.tokens) {
            b.customStatement(
              'INSERT OR IGNORE INTO chat_search_tokens '
              '(token, message_id, thread_id, sent_at_ms) VALUES (?, ?, ?, ?)',
              [token, e.messageId, threadId, e.sentAtMs],
            );
          }
          b.customStatement(
            'INSERT OR REPLACE INTO chat_search_state '
            '(message_id, thread_id, sent_at_ms, version) VALUES (?, ?, ?, ?)',
            [e.messageId, threadId, e.sentAtMs, version],
          );
        }
      });
    });
  }

  Future<void> removeFromSearchIndex(List<String> messageIds) async {
    if (messageIds.isEmpty) return;
    for (var i = 0; i < messageIds.length; i += 500) {
      final chunk = messageIds.sublist(
        i,
        i + 500 > messageIds.length ? messageIds.length : i + 500,
      );
      final marks = List.filled(chunk.length, '?').join(',');
      await customStatement(
        'DELETE FROM chat_search_tokens WHERE message_id IN ($marks)',
        chunk,
      );
      await customStatement(
        'DELETE FROM chat_search_state WHERE message_id IN ($marks)',
        chunk,
      );
    }
  }

  Future<void> clearSearchIndexForThread(String threadId) async {
    await customStatement(
      'DELETE FROM chat_search_tokens WHERE thread_id = ?',
      [threadId],
    );
    await customStatement(
      'DELETE FROM chat_search_state WHERE thread_id = ?',
      [threadId],
    );
  }

  /// Ids and send times of messages containing *every* token, newest first.
  Future<List<({String messageId, int sentAtMs})>> searchChatIndex(
    String threadId,
    List<String> tokens, {
    int limit = 10000,
  }) async {
    final unique = tokens.toSet().toList();
    if (unique.isEmpty) return const [];
    final marks = List.filled(unique.length, '?').join(',');
    final rows = await customSelect(
      'SELECT message_id, MAX(sent_at_ms) AS sent_at_ms '
      'FROM chat_search_tokens '
      'WHERE thread_id = ? AND token IN ($marks) '
      'GROUP BY message_id '
      'HAVING COUNT(DISTINCT token) = ? '
      'ORDER BY sent_at_ms DESC, message_id DESC '
      'LIMIT ?',
      variables: [
        Variable<String>(threadId),
        for (final t in unique) Variable<String>(t),
        Variable<int>(unique.length),
        Variable<int>(limit),
      ],
    ).get();
    return [
      for (final r in rows)
        (
          messageId: r.read<String>('message_id'),
          sentAtMs: r.read<int>('sent_at_ms'),
        ),
    ];
  }

  /// Cached messages not yet indexed at [version], newest first.
  Future<List<CachedChatMessage>> getUnindexedCachedMessages(
    String threadId, {
    required int version,
    int limit = 200,
  }) async {
    final rows = await customSelect(
      'SELECT m.* FROM chat_messages m '
      'LEFT JOIN chat_search_state s '
      'ON s.message_id = m.message_id AND s.version >= ? '
      'WHERE m.thread_id = ? AND s.message_id IS NULL '
      'ORDER BY m.sent_at_ms DESC LIMIT ?',
      variables: [
        Variable<int>(version),
        Variable<String>(threadId),
        Variable<int>(limit),
      ],
      readsFrom: {chatMessages},
    ).get();
    return [for (final r in rows) chatMessages.map(r.data)];
  }

  /// How many cached messages still need indexing at [version].
  Future<int> countUnindexedCachedMessages(
    String threadId, {
    required int version,
  }) async {
    final row = await customSelect(
      'SELECT COUNT(*) AS c FROM chat_messages m '
      'LEFT JOIN chat_search_state s '
      'ON s.message_id = m.message_id AND s.version >= ? '
      'WHERE m.thread_id = ? AND s.message_id IS NULL',
      variables: [Variable<int>(version), Variable<String>(threadId)],
      readsFrom: {chatMessages},
    ).getSingle();
    return row.read<int>('c');
  }

  /// Every cached message in a thread, oldest-last, for in-chat search.
  Future<List<CachedChatMessage>> getAllCachedMessages(String threadId) async {
    return (select(chatMessages)
          ..where((m) => m.threadId.equals(threadId))
          ..orderBy([
            (m) => OrderingTerm(
              expression: m.sentAtMs,
              mode: OrderingMode.desc,
            ),
          ]))
        .get();
  }

  /// Every cached message across all threads, for chat backups.
  Future<List<CachedChatMessage>> getEveryCachedMessage() {
    return select(chatMessages).get();
  }

  /// Settings rows whose key starts with [prefix].
  Future<List<AppSettingEntry>> getAppSettingsWithPrefix(String prefix) {
    return (select(appSettings)..where((s) => s.key.like('$prefix%'))).get();
  }

  // =========================================================================
  // OUTBOX QUERIES
  // =========================================================================

  /// Queue a message for delivery, oldest first on read.
  Future<void> enqueueOutbox(OutboxMessagesCompanion entry) async {
    await into(outboxMessages).insertOnConflictUpdate(entry);
  }

  Future<List<OutboxEntry>> getOutboxEntries() {
    return (select(outboxMessages)..orderBy([
          (o) => OrderingTerm(expression: o.queuedAtMs),
        ]))
        .get();
  }

  Future<List<OutboxEntry>> getOutboxForThread(String threadId) {
    return (select(outboxMessages)
          ..where((o) => o.threadId.equals(threadId))
          ..orderBy([(o) => OrderingTerm(expression: o.queuedAtMs)]))
        .get();
  }

  Future<void> deleteOutboxEntry(String messageId) async {
    await (delete(
      outboxMessages,
    )..where((o) => o.messageId.equals(messageId))).go();
  }

  /// Record a failed attempt so the UI can show the message as unsent.
  Future<void> markOutboxFailure(String messageId, String error) async {
    final row = await (select(
      outboxMessages,
    )..where((o) => o.messageId.equals(messageId))).getSingleOrNull();
    if (row == null) return;
    await (update(outboxMessages)
          ..where((o) => o.messageId.equals(messageId)))
        .write(
          OutboxMessagesCompanion(
            attempts: Value(row.attempts + 1),
            lastError: Value(error),
          ),
        );
  }

  /// Generic key/value settings row, reused for small per-device flags (e.g.
  /// the local "clear chat" watermark) that do not need a dedicated table.
  Future<void> upsertAppSetting(String key, String value) async {
    await into(appSettings).insertOnConflictUpdate(
      AppSettingsCompanion.insert(
        key: key,
        value: value,
        updatedAtMs: DateTime.now().toUtc().millisecondsSinceEpoch,
      ),
    );
  }

  Future<String?> getAppSetting(String key) async {
    final row = await (select(
      appSettings,
    )..where((s) => s.key.equals(key))).getSingleOrNull();
    return row?.value;
  }

  Future<void> deleteAppSetting(String key) async {
    await (delete(appSettings)..where((s) => s.key.equals(key))).go();
  }

  /// Clear all tables (for testing or reset vault).
  Future<void> clearAllTables() async {
    await delete(photos).go();
    await delete(albums).go();
    await delete(tags).go();
    await delete(photoTags).go();
    await delete(vault).go();
    await delete(thumbnails).go();
    await delete(syncState).go();
    await delete(backupState).go();
    await delete(encryptionVersions).go();
    await delete(importJobs).go();
    await delete(shareExports).go();
    await delete(trashItems).go();
    await delete(appSettings).go();
    await delete(securityEvents).go();
    await delete(chatMessages).go();
    await customStatement('DELETE FROM chat_search_tokens');
    await customStatement('DELETE FROM chat_search_state');
  }

  static String _jsonEncode(Map<String, dynamic> data) => data.toString();
}

